// --- Patient matching helpers (same logic in upsert + recovery) ---
// Strip leading status icons (⏳ ✅ 🔔 ...) and stray punctuation from a name
function cleanName(n) {
  return String(n || '')
    .replace(/^[^\p{L}\p{N}]+/u, '')
    .replace(/\s+/g, ' ')
    .replace(/[\s.,;:\-]+$/, '')
    .trim();
}
function nameKey(n) {
  return cleanName(n).toLowerCase();
}
// Normalize to +359 international format (text-safe for Google Sheets)
function toInternational(p) {
  let phone = String(p || '').replace(/[\s()\-.\/]/g, '');
  if (!phone) return '';
  if (phone.startsWith('00359')) phone = '+359' + phone.slice(5);
  else if (phone.startsWith('359')) phone = '+' + phone;
  else if (phone.startsWith('0') && phone.length >= 10) phone = '+359' + phone.slice(1);
  else if (/^[89]\d{8}$/.test(phone)) phone = '+359' + phone;
  else if (!phone.startsWith('+') && phone.length >= 9) phone = '+359' + phone;
  return phone;
}
// Core digits for comparison: +359887493315 / 0887493315 / 887493315 -> 887493315
function phoneKey(p) {
  return String(p || '').replace(/\D/g, '').replace(/^00/, '').replace(/^359/, '').replace(/^0/, '');
}
function isBlockName(n) {
  return /блокиран|почивка|отпуск|blocked/i.test(String(n || ''));
}

// Find the target row. The client sends the row number it saw plus the
// original name/phone; rows can shift (other deletes), so the row number is
// only trusted when that row still holds the same patient.
function locate(rows, body) {
  const wantName = nameKey(body.originalName);
  const wantPhone = phoneKey(body.originalPhone);
  const same = r => nameKey(r.name) === wantName && phoneKey(r.phone) === wantPhone;
  const byNumber = rows.find(r => Number(r.row_number) === Number(body.rowNumber));
  if (byNumber && same(byNumber)) return byNumber;
  return rows.find(same) || null;
}
const rows = $('Read Patients').all().map(i => i.json).filter(r => r && r.row_number);
const body = $('Webhook').first().json.body || {};
const target = locate(rows, body);

if (!target) {
  return [{ json: { ok: false, error: 'Пациентът не е намерен (може би вече е изтрит). Обновете списъка.' } }];
}
return [{ json: { ok: true, rowNumber: Number(target.row_number), name: target.name, phone: String(target.phone || '') } }];
